const $=s=>document.querySelector(s), esc=v=>String(v).replace(/[&<>'"]/g,c=>({ '&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'})[c]);
let selected=null;
async function json(url){const r=await fetch(url,{cache:'no-store'});if(!r.ok)throw Error();return r.json()}
function duration(seconds){if(seconds===null||seconds===undefined)return '—';const h=Math.floor(seconds/3600),m=Math.floor(seconds%3600/60),s=seconds%60;return `${h?`${h}:`:''}${String(m).padStart(h?2:1,'0')}:${s.toFixed(1).padStart(4,'0')}`}
function teamMarkup(data){return `<div class="race-grid single"><article class="race-table"><header><div><span>Live standings</span><h3>Team race</h3></div><b>${data.teams.length} teams</b></header><div class="table-scroll"><table><thead><tr><th>Pos</th><th>Team</th><th>Laps</th><th>Reached total</th><th>Fastest lap</th></tr></thead><tbody>${data.teams.map((team,index)=>`<tr class="${index<3?'podium':''}"><td class="place">${index+1}</td><td><strong>${esc(team.name)}</strong></td><td class="time">${team.laps}</td><td class="time">${duration(team.completion)}</td><td class="time">${duration(team.fastest)}</td></tr>`).join('')}</tbody></table></div><div class="note">Every Base finish counts for the rider and their team. <a href="/teams/"><strong>View all individual laps →</strong></a></div></article></div>`}
async function render(){try{const [feed,team]=await Promise.all([json('/api/public/events'),json('/api/public/team-race')]);const teamEvent={id:'team',name:'Team Race',count:team.teams.reduce((sum,item)=>sum+item.laps,0)};const events=[...feed.events,teamEvent];$('#status-badge').textContent=feed.status;if(!selected||!events.some(e=>String(e.id)===String(selected)))selected=String(events[0]?.id||'team');$('#event-tabs').innerHTML=events.map(e=>`<button class="tab ${String(e.id)===String(selected)?'active':''}" data-id="${e.id}">${esc(e.name)}</button>`).join('');$('#event-tabs').querySelectorAll('button').forEach(b=>b.onclick=()=>{selected=b.dataset.id;render()});const event=events.find(e=>String(e.id)===String(selected));if(!event){$('#race-title').textContent='No published results';return}$('#race-title').textContent=event.name;$('#round-nav').innerHTML='';if(selected==='team'){$('#result-count').textContent=teamEvent.count?`${teamEvent.count} completed laps · team race`:'Waiting for Base finishes';$('#stage-results').innerHTML=teamEvent.count?teamMarkup(team):'<div class="empty">Waiting for the first team-race finish.</div>';return}const rows=await json(`/api/public/events/${selected}/results`);$('#result-count').textContent=`${rows.length} recorded riders`;$('#stage-results').innerHTML=`<div class="race-grid single"><article class="race-table"><header><div><span>Live standings</span><h3>${esc(event.name)}</h3></div><b>${rows.length} riders</b></header><div class="table-scroll"><table><thead><tr><th>Pos</th><th>Rider</th><th>Time</th></tr></thead><tbody>${rows.map((r,i)=>`<tr class="${i<3?'podium':''}"><td class="place">${r.position}</td><td><span class="rider"><span class="bib">${esc(r.bib)}</span><span class="name">${esc(r.name)}</span></span></td><td class="time">${esc(r.time)}</td></tr>`).join('')}</tbody></table></div></article></div>`}catch{$('#race-title').textContent='Waiting for timing feed';$('#result-count').textContent='The live results service is not connected yet.'}}
render();setInterval(render,15000);
